import os
import requests

def validate_document_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("AFFINDA_API_KEY")
    if not api_key:
        raise ValueError("Missing Affinda API key. Set AFFINDA_API_KEY or pass config['api_key'].")
    base_url = config.get("base_url", "https://api.affinda.com")
    endpoint = f"{base_url}/v2/documents"
    files = {}
    data = {}
    headers = {
        "Authorization": f"Bearer {api_key}",
    }

    if isinstance(payload, dict):
        if "file_path" in payload:
            files["file"] = open(payload["file_path"], "rb")
        elif "file_bytes" in payload:
            filename = payload.get("filename", "document.pdf")
            content_type = payload.get("content_type", "application/pdf")
            files["file"] = (filename, payload["file_bytes"], content_type)
        else:
            raise ValueError("payload must include 'file_path' or 'file_bytes' when passing a dict.")
        if payload.get("workspace"):
            data["workspace"] = payload["workspace"]
        if payload.get("collection"):
            data["collection"] = payload["collection"]
    else:
        raise ValueError("payload must be a dict containing document input.")

    try:
        response = requests.post(endpoint, headers=headers, data=data, files=files, timeout=config.get("timeout", 60))
        response.raise_for_status()
        parsed = response.json()
    finally:
        file_obj = files.get("file")
        if hasattr(file_obj, "close"):
            file_obj.close()

    extracted = parsed.get("data", {})
    required_fields = config.get("required_fields", [])
    min_confidence = float(config.get("min_confidence", 0.0))

    normalized_fields = {}
    validations = {}

    for field_name in required_fields:
        field_value = extracted.get(field_name)
        present = field_value is not None
        confidence = None

        if isinstance(field_value, dict):
            confidence = field_value.get("confidence")
            value = field_value.get("value", field_value)
        else:
            value = field_value

        valid = present and (confidence is None or float(confidence) >= min_confidence)
        normalized_fields[field_name] = value
        validations[field_name] = {
            "present": present,
            "confidence": confidence,
            "valid": valid,
        }

    result = {
        "provider": "Affinda",
        "document_id": parsed.get("identifier"),
        "fields": normalized_fields,
        "validations": validations,
        "all_valid": all(v["valid"] for v in validations.values()) if required_fields else True,
        "raw_response": parsed,
    }
    return result
